#!/bin/bash
# HackiGalaxy build (ProjectArcadeX style):  ./build.sh <codename> [xnu-payload.bin]   |  ./build.sh  (lists devices)
set -euo pipefail
cd "$(dirname "$0")"; ROOT=$PWD
AVAILABLE=$(ls objectives | grep -v '^template$' | tr '\n' ' ')
DEVICE="${1:-${DEVICE:-}}"
[ -n "$DEVICE" ] && [ -f objectives/$DEVICE/$DEVICE.sh ] || { echo "usage: $0 <codename> [payload]   available: $AVAILABLE"; exit 1; }
source objectives/$DEVICE/$DEVICE.sh; source platform/$PLATFORM/platform.sh
cat > shim/device.h <<H
/* generated by build.sh for $DEVICE ($MARKETING) - do not edit */
#pragma once
#define DEVICE_NAME "$DEVICE"
#define UFS_BASE $UFS_BASE
#define GICD_BASE $GICD_BASE
#define GICR_BASE $GICR_BASE
#define GICR_SIZE $GICR_SIZE
#define GICR_PE_SIZE $GICR_PE_SIZE
#define PSHOLD $PSHOLD
#define IMEM_RESTART_REASON $IMEM_RESTART_REASON
#define FB_BASE $FB_BASE
#define FB_W $FB_W
#define FB_H $FB_H
#define FB_STRIDE (FB_W * 4)
H
CC=${CC:-aarch64-linux-gnu-gcc}; OC=${OC:-aarch64-linux-gnu-objcopy}; NM=${NM:-aarch64-linux-gnu-nm}
F="-O2 -ffreestanding -nostdlib -fno-pic -mgeneral-regs-only -mstrict-align -fno-stack-protector -Wall -Wextra"
O=$ROOT/out/$DEVICE; mkdir -p $O
S="start.S shim.c console.c mmu.c fdt.c loader.c ufs.c"
cd shim
for f in $S; do $CC $F -I. -c $f -o $O/${f%.*}.o; done
$CC $F -static -T shim.ld -Wl,--build-id=none -Wl,--no-warn-rwx-segments -Wl,-N $(for f in $S; do echo $O/${f%.*}.o; done) -o $O/shim.elf
cd ..
$OC -O binary $O/shim.elf $O/Image
truncate -s $((16#$($NM $O/shim.elf | awk '$3=="_end"{print $1}'))) $O/Image
if [ -n "${2:-}" ]; then cp "$2" $O/ramdisk.bin
else (cd $O && rm -rf rd && mkdir rd && cd rd && touch x && echo x | cpio -o -H newc --quiet | gzip -9 > ../ramdisk.bin; cd .. && rm -rf rd); fi
MKB=$(command -v mkbootimg || command -v mkbootimg.py || echo "$ROOT/tools/mkbootimg/mkbootimg.py")
if [ -f "$MKB" ] || command -v "$MKB" >/dev/null; then
  python3 "$MKB" --header_version 4 --kernel $O/Image --ramdisk $O/ramdisk.bin --cmdline "console=null" -o $O/boot.img 2>&1 | tail -2 \
    || echo "mkbootimg failed"
else echo "mkbootimg not found (get AOSP system/tools/mkbootimg into tools/mkbootimg/): raw Image only"; fi
rm -f $O/*.o; ls -l $O
